import Sec1 from "./Sec1";
import Sec2 from "./Sec2";
import Sec3 from "./Sec3";
import { useTranslation } from 'react-i18next';

function Section(){
	const { t, i18n } = useTranslation();

	

	return(
		<>
			<Sec1 props={t.sec1}/>
			<Sec2 props={t.sec2}/>
			<Sec3 props={t.sec3}/>
		</>
	)
}

export default Section;
